-- Files attached to leads, deals, contacts and companies. The bytes live in file storage (see lib/files.ts) under
-- `storage_key`, which is generated by the server and never derived from the uploaded file name.
CREATE TABLE attachments (
  id            bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  workspace_id  bigint NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  entity_type   text NOT NULL CHECK (entity_type IN ('lead','deal','contact','company')),
  entity_id     bigint NOT NULL,
  file_name     text NOT NULL,
  content_type  text NOT NULL,
  size_bytes    bigint NOT NULL CHECK (size_bytes >= 0),
  sha256        text NOT NULL,
  storage_key   text NOT NULL UNIQUE,
  uploaded_by   bigint REFERENCES users(id) ON DELETE SET NULL,
  created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX attachments_record ON attachments (workspace_id, entity_type, entity_id, created_at DESC);
